INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q742306', 'Caesar''s invasions of Britain', 'In the course of his Gallic Wars, Julius Caesar invaded Britain twice: in 55 and 54 BC. On the first occasion, Caesar took with him only two legions, and achieved little beyond a landing on the coast of Kent. The second invasion was more substantial, consisting of 800 ships, five legions and 2,000 cavalry.', -56, NULL, NULL, NULL, NULL, NULL, 'year', '56 BCE', 64, 'https://en.wikipedia.org/wiki/Julius_Caesar''s_invasions_of_Britain'),
  ('Q1127337', 'Battle of Mons Graupius', 'The Battle of Mons Graupius was, according to Tacitus, a Roman military victory in what is now Scotland, taking place in AD 83 or, less probably, 84. The exact location of the battle is a matter of debate.', 83, NULL, NULL, NULL, NULL, NULL, 'year', '83', 65, 'https://en.wikipedia.org/wiki/Battle_of_Mons_Graupius'),
  ('Q595320', 'Battle of Badon', 'The Battle of Badon, also known as the Battle of Mons Badonicus, was purportedly fought between Britons and Anglo-Saxons in Post-Roman Britain during the early 6th century. It was credited as a major victory for the Britons, stopping the westward encroachment of the Anglo-Saxon kingdoms for a period.', 500, NULL, NULL, NULL, NULL, NULL, 'year', '500', 64, 'https://en.wikipedia.org/wiki/Battle_of_Badon'),
  ('Q2305651', 'Battle of Edington', 'The Battle of Edington or Battle of Ethandun was fought in May 878 between the West Saxon army of King Alfred the Great and the Great Heathen Army led by the Danish warlord Guthrum. The battle took place near Edington in Wiltshire, where Alfred secured a decisive victory that halted the Viking advance into Wessex.', 878, 5, NULL, NULL, NULL, NULL, 'month', 'May 878', 62, 'https://en.wikipedia.org/wiki/Battle_of_Edington'),
  ('Q2246615', 'Battle of Brunanburh', 'The Battle of Brunanburh was fought in 937 between Æthelstan, King of England, and an alliance of Olaf Guthfrithson, King of Dublin; Constantine II, King of Scotland; and Owain, King of Strathclyde. The battle is sometimes cited as the point of origin for English national identity: historians such as Michael Livingston argue that "the men who fought and died on that field forged a political map of the future that remains, arguably making the Battle of Brunanburh one of the most significant battles in the long history not just of England, but of the whole of the British Isles." Following an…', 937, NULL, NULL, NULL, NULL, NULL, 'year', '937', 61, 'https://en.wikipedia.org/wiki/Battle_of_Brunanburh'),
  ('Q83224', 'Battle of Hastings', 'The Battle of Hastings was fought on 14 October 1066 between the Norman-French army of William, Duke of Normandy, and an English army under the Anglo-Saxon King Harold Godwinson, beginning the Norman Conquest of England. It took place approximately 7 mi (11 km) northwest of Hastings, close to the present-day town of Battle, East Sussex, and was a decisive Norman victory.', 1066, 10, 14, NULL, NULL, NULL, 'day', '14 October 1066', 83, 'https://en.wikipedia.org/wiki/Battle_of_Hastings'),
  ('Q203225', 'Battle of Stamford Bridge', 'The Battle of Stamford Bridge took place at the village of Stamford Bridge, East Riding of Yorkshire, in England, on 25 September 1066, between an English army under King Harold Godwinson and an invading Norwegian force led by King Harald Hardrada and the English king''s brother Tostig Godwinson. After a bloody battle, both Hardrada and Tostig, along with most of the Norwegians, were killed.', 1066, 9, 25, NULL, NULL, NULL, 'day', '25 September 1066', 76, 'https://en.wikipedia.org/wiki/Battle_of_Stamford_Bridge'),
  ('Q1113659', 'Battle of Fulford', 'The Battle of Fulford was fought on the outskirts of the village of Fulford, just south of York in England, on 20 September 1066. King Harald III of Norway, also known as Harald Hardrada, a claimant to the English throne, and Tostig Godwinson, his English ally, fought and defeated the Northern Earls Edwin and Morcar.', 1066, 9, 20, NULL, NULL, NULL, 'day', '20 September 1066', 65, 'https://en.wikipedia.org/wiki/Battle_of_Fulford'),
  ('Q1339928', 'Battle of Evesham', 'The Battle of Evesham (4 August 1265) was one of the two main battles of 13th century England''s Second Barons'' War. It marked the defeat of Simon de Montfort, Earl of Leicester, and the rebellious barons by the future King Edward I, who led the forces of his father, King Henry III. It took place on 4 August 1265, near the town of Evesham, Worcestershire.', 1265, 8, 4, NULL, NULL, NULL, 'day', '4 August 1265', 61, 'https://en.wikipedia.org/wiki/Battle_of_Evesham'),
  ('Q499626', 'Battle of Stirling Bridge', 'The Battle of Stirling Bridge (Scottish Gaelic: Blàr Drochaid Shruighlea) was fought during the First War of Scottish Independence. On 11 September 1297, the forces of Andrew Moray and William Wallace defeated the combined English forces of John de Warenne, 6th Earl of Surrey, and Hugh de Cressingham near Stirling, on the River Forth.', 1297, 9, 11, NULL, NULL, NULL, 'day', '11 September 1297', 71, 'https://en.wikipedia.org/wiki/Battle_of_Stirling_Bridge'),
  ('Q589318', 'Battle of Falkirk', 'The Battle of Falkirk (Scottish Gaelic: Blàr na h-Eaglaise Brice; Scots: Battle o Fawkirk), on 22 July 1298, was one of the major battles in the First War of Scottish Independence. Led by King Edward I of England, the English army defeated the Scots, led by William Wallace.', 1298, 7, 22, NULL, NULL, NULL, 'day', '22 July 1298', 71, 'https://en.wikipedia.org/wiki/Battle_of_Falkirk'),
  ('Q222520', 'Battle of Bannockburn', 'The Battle of Bannockburn (Scottish Gaelic: Blàr Allt nam Bànag or Blàr Allt a'' Bhonnaich) was fought on 23–24 June 1314, between the army of Robert the Bruce, King of Scots, and the army of King Edward II of England, during the First War of Scottish Independence. It was a decisive victory for Robert Bruce and formed a major turning point in the war, which ended 14 years later with the de jure restoration of Scottish independence under the Treaty of Edinburgh–Northampton.', 1314, 6, 23, 1314, 6, 24, 'day', '23 June 1314 – 24 June 1314', 75, 'https://en.wikipedia.org/wiki/Battle_of_Bannockburn'),
  ('Q498871', 'Peasants'' Revolt of 1381', 'The Peasants'' Revolt, also named Wat Tyler''s Rebellion or the Great Uprising, was a major uprising across large parts of England in 1381. The revolt had various causes, including the socio-economic and political tensions generated by the Black Death in the 1340s, the high taxes resulting from the conflict with France during the Hundred Years'' War, and instability within the local leadership of London.', 1381, 11, NULL, 1381, 11, NULL, 'month', 'November 1381', 73, 'https://en.wikipedia.org/wiki/Peasants''_Revolt'),
  ('Q842796', 'First Battle of St Albans', 'The First Battle of St Albans took place on 22 May 1455, at St Albans, 22 miles (35 km) north of London, and traditionally marks the beginning of the Wars of the Roses in England. Richard, Duke of York, and his allies, the Neville Earls of Salisbury and Warwick, defeated a royal army commanded by Edmund Beaufort, Duke of Somerset.', 1455, 5, 22, NULL, NULL, NULL, 'day', '22 May 1455', 64, 'https://en.wikipedia.org/wiki/First_Battle_of_St_Albans'),
  ('Q581401', 'Battle of Blore Heath', 'The Battle of Blore Heath took place during the English Wars of the Roses on 23 September 1459, at Blore Heath, Staffordshire. Blore Heath is a sparsely populated area of farmland two miles east of the town of Market Drayton in Shropshire, and close to the village of Loggerheads, Staffordshire.', 1459, 9, 23, NULL, NULL, NULL, 'day', '23 September 1459', 60, 'https://en.wikipedia.org/wiki/Battle_of_Blore_Heath'),
  ('Q906912', 'Battle of Wakefield', 'The ''Battle'' of Wakefield has traditionally been said to have taken place in Sandal Magna near Wakefield in northern England, on 30 December 1460. Recent research demonstrates that it was not a battle in the proper sense of a word, but a small-scale skirmish that resulted in the capture and subsequent deaths of Richard of York, 3rd Duke of York, his second son, Edmund, Earl of Rutland, and Richard Neville, 5th Earl of Salisbury.', 1460, 12, 30, NULL, NULL, NULL, 'day', '30 December 1460', 62, 'https://en.wikipedia.org/wiki/Battle_of_Wakefield'),
  ('Q634629', 'Battle of Towton', 'The Battle of Towton took place on 29 March 1461 during the Wars of the Roses, near Towton in North Yorkshire. Yorkist forces decisively defeated Lancastrian supporters of Henry VI, securing the English throne for Edward IV. Fought for ten hours between an estimated 50,000 soldiers from both sides in a snowstorm on Palm Sunday, it was "probably the largest and bloodiest battle on English soil".', 1461, 3, 29, NULL, NULL, NULL, 'day', '29 March 1461', 65, 'https://en.wikipedia.org/wiki/Battle_of_Towton'),
  ('Q1337059', 'Battle of Tewkesbury', 'The Battle of Tewkesbury (4 May 1471) was one of the most decisive battles of the Wars of the Roses in England. King Edward IV and his forces loyal to the House of York completely defeated those of the rival House of Lancaster.', 1471, 5, 4, NULL, NULL, NULL, 'day', '4 May 1471', 64, 'https://en.wikipedia.org/wiki/Battle_of_Tewkesbury'),
  ('Q1428169', 'Battle of Barnet', 'The Battle of Barnet was a decisive Yorkist victory in the Wars of the Roses, a dynastic conflict of 15th-century England. The military action, along with the subsequent Battle of Tewkesbury, secured the throne for Edward IV. On Sunday 14 April 1471, Easter Day, near Barnet, then a small Hertfordshire town north of London, Edward led the House of York in a fight against the House of Lancaster, which backed Henry VI for the throne.', 1471, 4, 14, NULL, NULL, NULL, 'day', '14 April 1471', 64, 'https://en.wikipedia.org/wiki/Battle_of_Barnet'),
  ('Q222013', 'Battle of Bosworth Field', 'The Battle of Bosworth or Bosworth Field ( BOZ-wərth) was the last significant battle of the Wars of the Roses, the civil war between the houses of Lancaster and York that extended across England and Wales in the latter half of the 15th century. Fought on 22 August 1485, the battle was won by an alliance of Lancastrians and disaffected Yorkists.', 1485, 8, 22, NULL, NULL, NULL, 'day', '22 August 1485', 73, 'https://en.wikipedia.org/wiki/Battle_of_Bosworth_Field'),
  ('Q2316201', 'Tudor period', 'In England and Wales, the Tudor period occurred between 1485 and 1603, including the Elizabethan era. The Tudor period coincides with the reign of the House of Tudor, which began with the accession of Henry VII and ended with the death of Elizabeth I. Under the Tudor dynasty, art, architecture, trade, exploration, and commerce flourished.', 1485, NULL, NULL, 1603, 3, 24, 'year', '1485 – 24 March 1603', 60, 'https://en.wikipedia.org/wiki/Tudor_period'),
  ('Q1300742', 'Battle of Flodden', 'The Battle of Flodden, Flodden Field, or occasionally Branxton or Brainston Moor was fought on 9 September 1513 between the Kingdom of England and the Kingdom of Scotland as part of the War of the League of Cambrai and resulted in an English victory. The battle was fought near Branxton, in the county of Northumberland, in northern England, between an invading Scots army under King James IV and an English army commanded by the Earl of Surrey.', 1513, 9, 9, NULL, NULL, NULL, 'day', '9 September 1513', 61, 'https://en.wikipedia.org/wiki/Battle_of_Flodden'),
  ('Q1233121', 'Pilgrimage of Grace', 'The Pilgrimage of Grace was an English Catholic popular revolt beginning in Yorkshire in October 1536 before spreading to other parts of Northern England, including Cumberland, Northumberland, Durham and north Lancashire. The protests occurred under the leadership of Robert Aske.', 1536, NULL, NULL, NULL, NULL, NULL, 'year', '1536', 61, 'https://en.wikipedia.org/wiki/Pilgrimage_of_Grace'),
  ('Q326417', 'Battle of Marston Moor', 'The Battle of Marston Moor was fought on 2 July 1644, during the Wars of the Three Kingdoms of 1639–1653. The combined forces of the English Parliamentarians under Lord Fairfax and the Earl of Manchester and the Scottish Covenanters under the Earl of Leven defeated the Royalists commanded by Prince Rupert of the Rhine and the Marquess of Newcastle.', 1644, 7, 2, NULL, NULL, NULL, 'day', '2 July 1644', 61, 'https://en.wikipedia.org/wiki/Battle_of_Marston_Moor'),
  ('Q949724', 'Battle of Naseby', 'The Battle of Naseby took place on 14 June 1645 during the First English Civil War, near the village of Naseby in Northamptonshire. The Parliamentarian New Model Army, commanded by Sir Thomas Fairfax and Oliver Cromwell, destroyed the main Royalist army under Charles I and Prince Rupert.', 1645, 6, 14, NULL, NULL, NULL, 'day', '14 June 1645', 64, 'https://en.wikipedia.org/wiki/Battle_of_Naseby'),
  ('Q1116626', 'Battle of Worcester', 'The Battle of Worcester took place on 3 September 1651 in and around the city of Worcester, England and was the last major battle of the 1642 to 1651 Wars of the Three Kingdoms. A Parliamentarian army of around 28,000 under Oliver Cromwell defeated a largely Scottish Royalist force of 16,000 led by Charles II of England and Scotland.', 1651, 9, 3, NULL, NULL, NULL, 'day', '3 September 1651', 62, 'https://en.wikipedia.org/wiki/Battle_of_Worcester'),
  ('Q846848', 'Stuart Restoration', 'The Stuart Restoration was the return in May 1660 of the Stuart monarchy to the kingdoms of England, Scotland, and Ireland, ending the Interregnum and the Commonwealth of England that had been established after the execution of Charles I in January 1649. The Commonwealth had been governed by the Lord Protector Oliver Cromwell and, briefly, his son Richard Cromwell, before political instability and the intervention of General George Monck led to the Declaration of Breda and the return of Charles II from exile.', 1660, NULL, NULL, 1714, NULL, NULL, 'year', '1660–1714', 71, 'https://en.wikipedia.org/wiki/Stuart_Restoration'),
  ('Q651919', 'Battle of Culloden', 'The Battle of Culloden took place on 16 April 1746, near Inverness, in the Scottish Highlands. A Jacobite army under Charles Edward Stuart was decisively defeated by a British government force commanded by the Duke of Cumberland, thereby ending the Jacobite rising of 1745.', 1746, 4, 27, NULL, NULL, NULL, 'day', '27 April 1746', 71, 'https://en.wikipedia.org/wiki/Battle_of_Culloden'),
  ('Q1049945', 'Jacobite rising of 1745', 'The Jacobite rising of 1745 was an attempt to regain the British throne for the exiled House of Stuart. The last in a series of Jacobite risings that began in March 1689, it proved to be the end of Jacobitism as a major factor in British politics.', 1746, 4, 20, 1746, NULL, NULL, 'day', '1746', 62, 'https://en.wikipedia.org/wiki/Jacobite_rising_of_1745'),
  ('Q2783102', 'London Beer Flood', 'The London Beer Flood was an accident at Meux & Co''s Horse Shoe Brewery, London, on 17 October 1814. It took place when one of the 22-foot-tall (6.7 m) wooden vats of fermenting porter burst.', 1814, 10, 17, NULL, NULL, NULL, 'day', '17 October 1814', 67, 'https://en.wikipedia.org/wiki/London_Beer_Flood'),
  ('Q649599', 'Treaty of 1818', 'The Convention respecting fisheries, boundary and the restoration of slaves, also known as the London Convention, Anglo-American Convention of 1818, Convention of 1818, or simply the Treaty of 1818, is an international treaty signed in 1818 between the United States and the United Kingdom. This treaty resolved long-standing boundary issues between the two signatories.', 1818, 10, 20, NULL, NULL, NULL, 'day', '20 October 1818', 61, 'https://en.wikipedia.org/wiki/Treaty_of_1818'),
  ('Q224794', 'Anglo-Dutch Treaty of 1824', 'The Anglo-Dutch Treaty of 1824, also known as the Treaty of London (Dutch: Verdrag van Londen), was a treaty between the United Kingdom and the Netherlands in London on 17 March 1824. The treaty was to resolve disputes arising from the execution of the Anglo-Dutch Treaty of 1814.', 1824, 3, 17, NULL, NULL, NULL, 'day', '17 March 1824', 60, 'https://en.wikipedia.org/wiki/Anglo-Dutch_Treaty_of_1824'),
  ('Q1160895', 'Treaty of London', 'The Treaty of London of 1839, was signed on 19 April 1839 between the major European powers, the United Kingdom of the Netherlands, and the Kingdom of Belgium. It was a direct follow-up to the 1831 Treaty of the XVIII Articles, which the Netherlands had refused to sign, and the result of negotiations at the London Conference of 1838–1839 which sought to maintain the Concert of Europe.', 1839, 4, 19, NULL, NULL, NULL, 'day', '19 April 1839', 71, 'https://en.wikipedia.org/wiki/Treaty_of_London_(1839)'),
  ('Q1345269', 'Treaty of London', 'The Treaty of London (French: Traité de Londres), often called the Second Treaty of London after the 1839 Treaty, granted Luxembourg full independence and neutrality. It was signed on 11 May 1867 in the aftermath of the Austro-Prussian War and the Luxembourg Crisis.', 1867, 5, 11, NULL, NULL, NULL, 'day', '11 May 1867', 61, 'https://en.wikipedia.org/wiki/Treaty_of_London_(1867)'),
  ('Q815102', 'Siege of Sidney Street', 'The siege of Sidney Street of January 1911, also known as the Battle of Stepney, was a gunfight in the East End of London between a combined police and army force and two Latvian revolutionaries. The siege was the culmination of a series of events that began in December 1910, with an attempted jewellery robbery at Houndsditch in the City of London by a gang of Latvian immigrants which resulted in the murder of three policemen, the wounding of two others, and the death of George Gardstein, a key member of the Latvian gang.', 1911, 1, 3, NULL, NULL, NULL, 'day', '3 January 1911', 60, 'https://en.wikipedia.org/wiki/Siege_of_Sidney_Street'),
  ('Q584617', 'Treaty of London', 'The Treaty of London (1913) was signed on 30 May following the London Conference of 1912–1913. It dealt with the territorial adjustments arising out of the conclusion of the First Balkan War.', 1913, 5, 30, NULL, NULL, NULL, 'day', '30 May 1913', 72, 'https://en.wikipedia.org/wiki/Treaty_of_London_(1913)'),
  ('Q824165', 'Treaty of London', 'The Treaty of London (Italian: Trattato di Londra; Russian: Лондонский договор, romanized: Londonskiy dogovor) or the Pact of London (Patto di Londra, French: Pacte de Londres) was a secret agreement concluded on 26 April 1915 by the United Kingdom, France, and Russia on the one part, and Italy on the other, in order to entice the latter to enter the Great War on the side of the Triple Entente. The agreement involved promises of Italian territorial expansion against Austria-Hungary, the Ottoman Empire and in Africa where it was promised enlargement of its colonies.', 1915, 4, 26, NULL, NULL, NULL, 'day', '26 April 1915', 75, 'https://en.wikipedia.org/wiki/Treaty_of_London_(1915)'),
  ('Q541191', 'Anglo-Irish Treaty', 'The 1921 Anglo-Irish Treaty (Irish: An Conradh Angla-Éireannach), commonly known in Ireland as The Treaty and officially the Articles of Agreement for a Treaty Between Great Britain and Ireland, was an agreement between the government of the United Kingdom of Great Britain and Ireland and the government of the Irish Republic that concluded the Irish War of Independence. It provided for the establishment of the Irish Free State within a year as a self-governing dominion within the "community of nations known as the British Empire", a status "the same as that of the Dominion of Canada".', 1921, 12, 6, NULL, NULL, NULL, 'day', '6 December 1921', 73, 'https://en.wikipedia.org/wiki/Anglo-Irish_Treaty'),
  ('Q704536', 'London Naval Treaty', 'The London Naval Treaty, officially the Treaty for the Limitation and Reduction of Naval Armament, was an agreement between the United Kingdom, Japan, France, Italy, and the United States that was signed on 22 April 1930. Seeking to address issues not covered in the 1922 Washington Naval Treaty, which had created tonnage limits for each nation''s surface warships, the new agreement regulated submarine warfare, further controlled cruisers and destroyers, and limited naval shipbuilding.', 1930, 4, 22, NULL, NULL, NULL, 'day', '22 April 1930', 61, 'https://en.wikipedia.org/wiki/London_Naval_Treaty'),
  ('Q719883', 'Statute of Westminster 1931', 'The Statute of Westminster 1931 (22 & 23 Geo. 5.', 1931, NULL, NULL, NULL, NULL, NULL, 'year', '1931', 71, 'https://en.wikipedia.org/wiki/Statute_of_Westminster_1931'),
  ('Q617634', 'Anglo-Egyptian treaty of 1936', 'The Anglo-Egyptian Treaty of 1936 (officially, The Treaty of Alliance Between His Majesty, in Respect of the United Kingdom, and His Majesty, the King of Egypt) was a treaty signed between the United Kingdom and the Kingdom of Egypt. The treaty significantly reduced Britain''s influence in Egypt''s domestic policy but Britain still had significant influence in Egypt''s foreign policy and defence, especially the Suez Canal.', 1936, 8, 26, NULL, NULL, NULL, 'day', '26 August 1936', 61, 'https://en.wikipedia.org/wiki/Anglo-Egyptian_treaty_of_1936'),
  ('Q913640', 'Great Smog of London', 'The Great Smog was a severe air pollution event that affected London, England, in December 1952. A period of unusually cold weather, combined with an anticyclone and windless conditions, collected airborne pollutants—mostly arising from the use of coal—to form a thick layer of smog over the city.', 1952, 12, NULL, 1952, 12, 9, 'month', 'December 1952 – 9 December 1952', 73, 'https://en.wikipedia.org/wiki/Great_Smog_of_London'),
  ('Q504934', 'North Sea flood of 1953', 'The North Sea flood of 1953, also known as the Big Flood or East Coast Flood (in England) or as the Flood Disaster (Dutch: Watersnoodramp), was a flood caused by a heavy storm surge in the North Sea that struck low-lying coastal areas of the Netherlands, Belgium, and the United Kingdom. More than 2,000 people were killed on land and hundreds more at sea.', 1953, 1, 31, 1953, 2, 1, 'day', '31 January 1953 – 1 February 1953', 67, 'https://en.wikipedia.org/wiki/North_Sea_flood_of_1953'),
  ('Q278960', 'Partial Nuclear Test Ban Treaty', 'The Partial Test Ban Treaty (PTBT), formally known as the 1963 Treaty Banning Nuclear Weapon Tests in the Atmosphere, in Outer Space and Under Water, prohibited all test detonations of nuclear weapons except for those conducted underground. It is also abbreviated as the Limited Test Ban Treaty (LTBT) and Nuclear Test Ban Treaty (NTBT), though the latter may also refer to the Comprehensive Nuclear-Test-Ban Treaty (CTBT), which succeeded the PTBT for ratifying parties.', 1963, 8, 5, NULL, NULL, NULL, 'day', '5 August 1963', 69, 'https://en.wikipedia.org/wiki/Partial_Nuclear_Test_Ban_Treaty'),
  ('Q190819', 'Bloody Sunday', 'Bloody Sunday, or the Bogside Massacre, occurred on 30 January 1972 when British soldiers shot 26 unarmed civilians during a protest march in the Bogside area of Derry, Northern Ireland. Thirteen men were killed outright, while the death of another man four months later has been attributed to his gunshot injuries.', 1972, 1, 30, NULL, NULL, NULL, 'day', '30 January 1972', 75, 'https://en.wikipedia.org/wiki/Bloody_Sunday_(1972)'),
  ('Q370706', 'Iranian Embassy Siege', 'The Iranian Embassy siege took place from 30 April to 5 May 1980, after a group of six armed men stormed the Iranian embassy on Prince''s Gate in South Kensington, London. The gunmen, Iranian Arabs campaigning for the sovereignty of the Khuzestan Province of Iran, took 26 people hostage, including embassy staff, several visitors, and a police officer who had been guarding the embassy.', 1980, 4, 30, 1980, 5, 5, 'day', '30 April 1980 – 5 May 1980', 64, 'https://en.wikipedia.org/wiki/Iranian_Embassy_siege'),
  ('Q211087', 'Pan Am Flight 103', 'Pan Am Flight 103 was a regularly scheduled Pan Am flight from Frankfurt to Detroit, with stopovers in London and New York City. Shortly after 19:00 GMT on 21 December 1988, the Boeing 747 Clipper Maid of the Seas operating the transatlantic leg of the flight was destroyed by a bomb while flying over the Scottish town of Lockerbie.', 1988, 12, 21, NULL, NULL, NULL, 'day', '21 December 1988', 73, 'https://en.wikipedia.org/wiki/Pan_Am_Flight_103'),
  ('Q234132', 'Hillsborough disaster', 'The Hillsborough disaster was a fatal crowd crush at a football match at Hillsborough Stadium in Sheffield, South Yorkshire, England, on 15 April 1989. It occurred during an FA Cup semi-final between Liverpool and Nottingham Forest in the two standing-only central pens within the Leppings Lane stand allocated to Liverpool supporters.', 1989, 4, 15, NULL, NULL, NULL, 'day', '15 April 1989', 71, 'https://en.wikipedia.org/wiki/Hillsborough_disaster'),
  ('Q435572', 'British Airways Flight 5390', 'British Airways Flight 5390 was a scheduled international passenger flight from Birmingham Airport in England to Málaga Airport in Spain. On 10 June 1990, the BAC One-Eleven suffered an explosive decompression.', 1990, 6, 10, NULL, NULL, NULL, 'day', '10 June 1990', 61, 'https://en.wikipedia.org/wiki/British_Airways_Flight_5390'),
  ('Q2193276', 'death of Diana, Princess of Wales', 'In the late hours of 31 August 1997, Diana, Princess of Wales, died from injuries sustained in a car crash in the Pont de l''Alma tunnel in Paris, France. Dodi Fayed, Diana''s partner, and the chauffeur Henri Paul were both found dead inside the car.', 1997, 8, 31, NULL, NULL, NULL, 'day', '31 August 1997', 61, 'https://en.wikipedia.org/wiki/Death_of_Diana%2C_Princess_of_Wales'),
  ('Q208958', 'Good Friday Agreement', 'The Good Friday Agreement or Belfast Agreement (Irish: Comhaontú Aoine an Chéasta or Comhaontú Bhéal Feirste; Ulster Scots: Guid Friday Greeance or Bilfawst Greeance) is a pair of agreements signed on 10 April (Good Friday) 1998 that ended most of the violence of the Troubles, an ethnic and national conflict in Northern Ireland since the late 1960s. It was a major development in the Northern Ireland peace process of the 1990s.', 1998, 4, 10, NULL, NULL, NULL, 'day', '10 April 1998', 75, 'https://en.wikipedia.org/wiki/Good_Friday_Agreement'),
  ('Q10818', '7 July 2005 London bombings', 'On 7 July 2005, Islamist terrorists carried out four coordinated suicide bombings targeting commuters travelling on London''s public transport during the morning rush hour. The attacks are sometimes known as the 7/7 bombings or simply 7/7.', 2005, 7, 7, NULL, NULL, NULL, 'day', '7 July 2005', 79, 'https://en.wikipedia.org/wiki/7_July_2005_London_bombings'),
  ('Q769736', 'British Airways Flight 38', 'British Airways Flight 38 was a scheduled international passenger flight from Beijing Capital International Airport in Beijing, China, to Heathrow Airport in London, United Kingdom, an 8,100-kilometre (4,400 nmi; 5,000 mi) trip. On 17 January 2008, the Boeing 777 aircraft crash-landed short of runway 27L at Heathrow.', 2008, 1, 17, NULL, NULL, NULL, 'day', '17 January 2008', 64, 'https://en.wikipedia.org/wiki/British_Airways_Flight_38'),
  ('Q15989108', 'Western African Ebola virus epidemic', 'The 2013–2016 epidemic of Ebola virus disease, centered in West Africa, was the most widespread outbreak of the disease in history. It caused major loss of life and socioeconomic disruption in the region, mainly in Guinea, Liberia and Sierra Leone.', 2013, 12, NULL, 2016, 6, NULL, 'month', 'December 2013 – June 2016', 78, 'https://en.wikipedia.org/wiki/Western_African_Ebola_epidemic'),
  ('Q21812812', '2016 United Kingdom European Union membership referendum', 'The 2016 United Kingdom European Union membership referendum, commonly referred to as the EU referendum or the Brexit referendum, was a referendum that took place on Thursday 23 June 2016 in the United Kingdom (UK) and Gibraltar under the provisions of the European Union Referendum Act 2015 to ask the electorate whether the country should continue to remain a member of, or leave, the European Union (EU). The result was a vote in favour of leaving the EU, triggering calls to begin the process of the country''s withdrawal from the EU commonly termed "Brexit".', 2016, 6, 23, NULL, NULL, NULL, 'day', '23 June 2016', 81, 'https://en.wikipedia.org/wiki/2016_United_Kingdom_European_Union_membership_referendum'),
  ('Q30274958', 'Grenfell Tower fire', 'On 14 June 2017, a high-rise fire broke out in the 24-storey Grenfell Tower block of flats in North Kensington, West London, England, at 00:54 BST and burned for 60 hours. A total of 70 people died at the scene and two other people died later in hospital, with more than 70 injured and 223 escaping.', 2017, 6, 14, NULL, NULL, NULL, 'day', '14 June 2017', 71, 'https://en.wikipedia.org/wiki/Grenfell_Tower_fire'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q107529288', '2021 European floods', 'In July 2021, several European countries were affected by severe floods. Some were catastrophic, causing deaths and widespread damage.', 2021, NULL, NULL, 2021, 7, 25, 'year', '2021', 73, 'https://en.wikipedia.org/wiki/2021_European_floods'),
  ('Q128281666', '2024 United Kingdom riots', 'From 30 July to 5 August 2024, far-right anti-immigration protests and riots occurred in England and Northern Ireland, within the United Kingdom, following the 2024 Southport stabbings, a targeted stabbing attack on 29 July 2024 at a dance class in Southport, England, which resulted in the deaths of three young girls. The riots took place amid false claims circulated by far-right groups, that the perpetrator of the attack was a Muslim and an asylum seeker, in addition to broader Islamophobic, racist, and anti-immigrant sentiments.', 2024, NULL, NULL, 2024, 8, 10, 'year', '2024', 60, 'https://en.wikipedia.org/wiki/2024_United_Kingdom_riots');
